export type Identifier = string;

export type Text = string;

export type Digest = string;

export type DecimalInteger = string;

export interface Provenance {
  readonly kind: "synthetic_fixture" | "frozen_inputs";
  readonly source: Text;
  readonly source_digest: Digest;
}

export interface OperatorSemantics {
  readonly name: Text;
  readonly definition: Text;
  readonly reference_digest: Digest;
}

export interface Target {
  readonly vendor: Identifier;
  readonly architecture: Identifier;
  readonly requirements: Readonly<Record<string, Text>>;
}

export type Strides = ReadonlyArray<number>;

export interface TensorDomain {
  readonly shape: ReadonlyArray<number>;
  readonly dtype: Identifier;
  readonly layout: Identifier;
  readonly strides?: Strides;
}

export interface CaseDomain {
  readonly weight: number;
  readonly inputs: Readonly<Record<string, TensorDomain>>;
  readonly outputs: Readonly<Record<string, TensorDomain>>;
}

export interface InputDomain {
  readonly casepack_digest: Digest;
  readonly cases: Readonly<Record<string, CaseDomain>>;
}

export interface FloatingTolerance {
  readonly kind: "floating";
  readonly atol: number;
  readonly rtol: number;
  readonly nan: "reject" | "same_positions";
  readonly inf: "reject" | "same_sign_and_positions";
  readonly comparison: "elementwise_abs_rel" | "complex_magnitude";
}

export interface IntegerTolerance {
  readonly kind: "integer";
  readonly exact: true;
  readonly sentinels: ReadonlyArray<DecimalInteger>;
}

export interface BooleanTolerance {
  readonly kind: "boolean";
  readonly exact: true;
}

export type Tolerance = FloatingTolerance | IntegerTolerance | BooleanTolerance;

export interface Specialization {
  readonly id: Identifier;
  readonly case_ids: ReadonlyArray<Identifier>;
  readonly assumptions: ReadonlyArray<Text>;
}

export interface SpecializationPolicy {
  readonly allowed: ReadonlyArray<Specialization>;
  readonly outside_domain: "reject";
}

export interface AliasingPolicy {
  readonly output_aliases: Readonly<Record<string, Identifier>>;
  readonly in_place: boolean;
}

export interface Baseline {
  readonly program_id: Identifier;
  readonly artifact_digest: Digest;
}

export interface OfficialScore {
  readonly kind: "official";
  readonly rule_id: Identifier;
  readonly direction: "maximize" | "minimize";
}

export interface GeometricSpeedupScore {
  readonly kind: "weighted_geomean_speedup";
  readonly direction: "maximize";
}

export interface MeanLatencyScore {
  readonly kind: "weighted_mean_latency";
  readonly direction: "minimize";
}

export type ScorePolicy = OfficialScore | GeometricSpeedupScore | MeanLatencyScore;

export interface UntimedLevel {
  readonly timing: false;
  readonly correctness_case_ids: ReadonlyArray<Identifier>;
}

export interface TimedLevel {
  readonly timing: true;
  readonly correctness_case_ids: ReadonlyArray<Identifier>;
  readonly warmup_iterations: number;
  readonly blocks: number;
  readonly samples_per_arm: number;
  readonly pairing: "parent_bracketed" | "alternating";
  readonly case_reducer: "mean" | "median";
  readonly minimum_effect: number;
  readonly confidence_level: number;
  readonly bootstrap_resamples: number;
}

export type MeasurementLevel = UntimedLevel | TimedLevel;

export interface MeasurementLevels {
  readonly smoke: MeasurementLevel;
  readonly quick: TimedLevel;
  readonly full: TimedLevel;
}

export interface MeasurementProtocol {
  readonly rule_id: Identifier;
  readonly levels: MeasurementLevels;
}

export interface CachePolicy {
  readonly mode: "hot" | "evicted" | "natural";
  readonly rule_id: Identifier;
}

export interface Synchronization {
  readonly before_interval: Text;
  readonly completion: "all_streams_in_interval";
}

export interface TimingPolicy {
  readonly scope: "kernel_only" | "end_to_end";
  readonly clock: "device_event" | "host_monotonic";
  readonly cache: CachePolicy;
  readonly synchronization: Synchronization;
  readonly input_preparation: "outside_interval";
  readonly profiling: "excluded";
}

export interface Budgets {
  readonly max_build_seconds: number;
  readonly max_evaluation_seconds: number;
  readonly max_total_seconds: number;
  readonly max_device_memory_bytes: number;
  readonly max_scratch_bytes: number;
}

export type QualityMetric = "compile_seconds" | "binary_bytes" | "cyclomatic_complexity" | "max_function_lines" | "specialization_paths" | "template_instantiations" | "unreachable_blocks" | "duplicate_blocks" | "registers" | "spill_bytes" | "new_warnings" | "logical_loc_growth_ratio";

export type QualityLimits = Readonly<Record<string, number>>;

export interface QualityTieBreak {
  readonly relative_score_tolerance: number;
  readonly metrics: ReadonlyArray<QualityMetric>;
  readonly final: "program_id_ascending";
}

export interface CleanupTriggers {
  readonly logical_loc_growth_ratio: number;
  readonly complexity_growth_ratio: number;
  readonly fork_count: number;
  readonly before_final_delivery: true;
}

export interface QualityPolicy {
  readonly rule_id: Identifier;
  readonly hard_limits: QualityLimits;
  readonly forbidden_patterns: ReadonlyArray<Text>;
  readonly tie_break: QualityTieBreak;
  readonly cleanup_triggers: CleanupTriggers;
}

export interface TaskContract {
  readonly schema_version: "kernelcat.task-contract/v1";
  readonly contract_id: Identifier;
  readonly revision: number;
  readonly purpose: "campaign" | "research";
  readonly provenance: Provenance;
  readonly operator: OperatorSemantics;
  readonly target: Target;
  readonly input_domain: InputDomain;
  readonly tolerances: Readonly<Record<string, Tolerance>>;
  readonly specialization_policy: SpecializationPolicy;
  readonly aliasing: AliasingPolicy;
  readonly allowed_calls: ReadonlyArray<Identifier>;
  readonly baseline: Baseline;
  readonly scoring: ScorePolicy;
  readonly measurement_protocol: MeasurementProtocol;
  readonly timing: TimingPolicy;
  readonly budgets: Budgets;
  readonly quality_policy: QualityPolicy;
}

export interface TaskContractSource {
  readonly source_digest: Digest;
  readonly contract: TaskContract;
}

export interface UnknownObservation {
  readonly status: "unknown";
  readonly reason: Text;
}

export interface DeviceProvenance {
  readonly status: "known";
  readonly device_id: Identifier;
  readonly pool_revision: Identifier;
  readonly vendor: Identifier;
  readonly architecture: Identifier;
}

export type DeviceObservation = DeviceProvenance | UnknownObservation;

export type EnvironmentObservation = Digest | UnknownObservation;

export interface MeasuredCase {
  readonly status: "measured";
  readonly baseline_ms: number;
  readonly candidate_ms: number;
}

export type CaseMeasurement = MeasuredCase | UnknownObservation;

export type CorrectnessVerdict = "passed" | "failed" | "unknown";

export type QualityNumber = number | UnknownObservation;

export type QualityInteger = number | UnknownObservation;

export type QualityDuration = number | UnknownObservation;

export interface QualityObservations {
  readonly compile_seconds?: QualityDuration;
  readonly binary_bytes?: QualityInteger;
  readonly cyclomatic_complexity?: QualityInteger;
  readonly max_function_lines?: QualityInteger;
  readonly specialization_paths?: QualityInteger;
  readonly template_instantiations?: QualityInteger;
  readonly unreachable_blocks?: QualityInteger;
  readonly duplicate_blocks?: QualityInteger;
  readonly registers?: QualityInteger;
  readonly spill_bytes?: QualityInteger;
  readonly new_warnings?: QualityInteger;
  readonly logical_loc_growth_ratio?: QualityNumber;
}

export type OfficialScoreObservation = number | UnknownObservation;

export interface ScoringObservation {
  readonly evaluation_id: Identifier;
  readonly receipt_revision: number;
  readonly receipt_digest: Digest;
  readonly stage: "screen" | "confirm" | "final";
  readonly program_id: Identifier;
  readonly artifact_digest: Digest;
  readonly task_contract_digest: Digest;
  readonly casepack_digest: Digest;
  readonly baseline: Baseline;
  readonly timing: TimingPolicy;
  readonly measurement_protocol: MeasurementProtocol;
  readonly environment: EnvironmentObservation;
  readonly device: DeviceObservation;
  readonly correctness: Readonly<Record<string, CorrectnessVerdict>>;
  readonly measurements: Readonly<Record<string, CaseMeasurement>>;
  readonly specialization_ids: ReadonlyArray<Identifier>;
  readonly quality_metrics: QualityObservations;
  readonly official_score?: OfficialScoreObservation;
}

export interface ScoringResultSet {
  readonly schema_version: "kernelcat.scoring-input/v1";
  readonly source_kind: "synthetic_fixture" | "evaluation_projection";
  readonly observations: ReadonlyArray<ScoringObservation>;
}
